package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtRec AmtRec
var scanner *bufio.Scanner

func storeWrap(d decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	trunc := d.Truncate(int32(scale))
	divisor := decimal.NewFromInt(1).Shift(int32(intDigits + scale))
	scaled := trunc.Shift(int32(scale))
	var scaledMod decimal.Decimal
	if scaled.Sign() < 0 {
		scaledMod = scaled.Abs().Mod(divisor).Neg()
	} else {
		scaledMod = scaled.Mod(divisor)
	}
	return scaledMod.Shift(-int32(scale))
}

func isOverflow(d decimal.Decimal, intDigits int, scale int) bool {
	trunc := d.Truncate(int32(scale))
	if trunc.Sign() < 0 {
		return true
	}
	divisor := decimal.NewFromInt(1).Shift(int32(intDigits + scale))
	scaled := trunc.Shift(int32(scale))
	return scaled.Abs().Cmp(divisor) >= 0
}

func formatEdited(val decimal.Decimal, picture string) string {
	dotPos := strings.Index(picture, ".")
	var before, after string
	var intDigits, fracDigits int
	if dotPos >= 0 {
		before = picture[:dotPos]
		after = picture[dotPos+1:]
		for _, ch := range before {
			if ch == 'Z' || ch == '9' {
				intDigits++
			}
		}
		for _, ch := range after {
			if ch == 'Z' || ch == '9' {
				fracDigits++
			}
		}
	} else {
		before = picture
		after = ""
		for _, ch := range before {
			if ch == 'Z' || ch == '9' {
				intDigits++
			}
		}
		fracDigits = 0
	}
	scale := fracDigits
	trunc := val.Truncate(int32(scale))
	truncAbs := trunc.Abs()
	fixedStr := truncAbs.StringFixed(int32(scale))
	var intStr, fracStr string
	if scale > 0 {
		parts := strings.SplitN(fixedStr, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		}
		if len(fracStr) < scale {
			fracStr = fracStr + strings.Repeat("0", scale-len(fracStr))
		} else if len(fracStr) > scale {
			fracStr = fracStr[:scale]
		}
	} else {
		intStr = fixedStr
		fracStr = ""
	}
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	} else if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	var outBefore strings.Builder
	intIdx := 0
	significant := false
	for _, ch := range before {
		if ch == 'Z' || ch == '9' {
			digit := intStr[intIdx]
			intIdx++
			if ch == 'Z' && digit == '0' && !significant {
				outBefore.WriteByte(' ')
			} else {
				outBefore.WriteByte(digit)
				if digit != '0' {
					significant = true
				} else {
					if significant {
						// keep true
					} else {
						if ch == '9' {
							// 9 zero alone does not make significant for earlier commas
						}
					}
				}
				if significant && digit == '0' {
					significant = true
				}
				if digit != '0' {
					significant = true
				}
			}
		} else if ch == ',' {
			if significant {
				outBefore.WriteByte(',')
			} else {
				outBefore.WriteByte(' ')
			}
		} else {
			outBefore.WriteByte(byte(ch))
		}
	}
	var outAfter strings.Builder
	fracIdx := 0
	for _, ch := range after {
		if ch == 'Z' || ch == '9' {
			var d byte = '0'
			if fracIdx < len(fracStr) {
				d = fracStr[fracIdx]
				fracIdx++
			}
			outAfter.WriteByte(d)
		} else if ch == ',' {
			outAfter.WriteByte(',')
		} else {
			outAfter.WriteByte(byte(ch))
		}
	}
	if dotPos >= 0 {
		return outBefore.String() + "." + outAfter.String()
	}
	return outBefore.String()
}

func formatUnedited(val int64, digits int) string {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	v := val % mod
	if v < 0 {
		v += mod
	}
	return fmt.Sprintf("%0*d", digits, v)
}

func readPara() {
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 11 {
			line = line + strings.Repeat(" ", 11-len(line))
		} else if len(line) > 11 {
			line = line[:11]
		}
		amtRec.ArAcct = line[0:4]
		amtStr := line[4:11]
		var digitBuilder strings.Builder
		for _, ch := range amtStr {
			if ch >= '0' && ch <= '9' {
				digitBuilder.WriteRune(ch)
			} else if ch == ' ' {
				digitBuilder.WriteByte('0')
			} else {
				digitBuilder.WriteByte('0')
			}
		}
		digits := digitBuilder.String()
		var intVal int64
		for _, ch := range digits {
			intVal = intVal*10 + int64(ch-'0')
		}
		amtRec.ArAmt = decimal.New(intVal, -2)
	} else {
		WsEofFlag = "Y"
	}
}

func overflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}

func processPara() {
	WsBigTotal = storeWrap(WsBigTotal.Add(amtRec.ArAmt), 7, 2)
	WsWrapTotal = storeWrap(WsBigTotal, 5, 2)

	tentative := WsSafeTotal.Add(amtRec.ArAmt)
	if isOverflow(tentative, 5, 2) {
		overflowPara()
	} else {
		WsSafeTotal = storeWrap(tentative, 5, 2)
	}

	WsCount = (WsCount + 1) % 100

	halfRaw := amtRec.ArAmt.Mul(decimal.NewFromInt(5)).Shift(-1)
	WsHalf = storeWrap(halfRaw, 5, 1)

	WsAmtEd = formatEdited(amtRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")

	line := amtRec.ArAcct + " " + WsAmtEd + " " + WsWrapEd + " " + WsSafeEd + " " + WsHalfEd
	fmt.Println(line)

	readPara()
}

func summaryPara() {
	fmt.Println("RECORDS: " + formatUnedited(WsCount, 2))
	fmt.Println("OVERFLOWS: " + formatUnedited(WsOverflows, 2))
}

func mainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner = bufio.NewScanner(f)
	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	summaryPara()
}

func main() {
	mainPara()
}
